corrected_code:
const express = require('express');
const Agenda = require('agenda');
const { ObjectId } = require('mongodb');
const { jwtAuth } = require('../auth');

const router = express.Router();
const agenda = new Agenda({ db: { address: process.env.MONGO_URI } });

router.delete('/api/reminders/:reminderId', jwtAuth, async (req, res) => {
  const result = await agenda.cancel({
    _id: new ObjectId(req.params.reminderId),
    'data.patientId': req.user.patientId,
  });
  if (result === 0) {
    return res.status(403).json({ error: 'Reminder not found or does not belong to your account' });
  }

  res.json({ cancelled: true, reminderId: req.params.reminderId });
});
